'use strict';

// Turning the report into a file.
//
// The report says which paths are noise; this writes that into `.aiignore`.
// It only ever appends: an existing line — a comment, a hand-written rule, a
// rule with different spacing — is left exactly as it is. Running twice adds
// nothing the second time.
//
// It does not claim the score will drop afterwards: the scan is a static
// heuristic over file names and sizes and does not read `.aiignore` yet.

const fs = require('fs');

const HEADER = [
  "# Files that waste an AI coding agent's context.",
  '# Generated by ai-context-doctor. Review before committing.'
];

function isRuleLine(line) {
  const trimmed = String(line).trim();
  return trimmed !== '' && !trimmed.startsWith('#');
}

function parseRules(text) {
  const rules = new Set();

  for (const line of text.split(/\r?\n/)) {
    if (isRuleLine(line)) rules.add(line.trim());
  }

  return rules;
}

function planAiignore({ existing, suggested }) {
  const known = existing === null ? new Set() : parseRules(existing);
  const added = [];

  for (const item of suggested) {
    const rule = String(item).trim();
    if (!isRuleLine(rule) || known.has(rule)) continue;
    known.add(rule);
    added.push(rule);
  }

  return { added, created: existing === null };
}

function renderAiignore({ existing, added, created }) {
  const rules = added.join('\n');

  if (created) return `${HEADER.join('\n')}\n\n${rules}\n`;

  // Keep everything the user already had, byte for byte, and only drop the
  // trailing whitespace before appending so the file ends in one newline.
  const body = existing.replace(/\s+$/, '');
  return body === '' ? `${rules}\n` : `${body}\n${rules}\n`;
}

function fail(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function writeAiignore(aiignorePath, suggested, options = {}) {
  const { dryRun = false } = options;
  let existing = null;

  if (fs.existsSync(aiignorePath)) {
    const stats = fs.lstatSync(aiignorePath);
    // Refuse anything that could write somewhere other than the scanned repo.
    if (stats.isSymbolicLink()) {
      throw fail(
        'is-a-symlink',
        `${aiignorePath} is a symbolic link; refusing to write through it.`
      );
    }
    if (!stats.isFile()) {
      throw fail('not-a-file', `${aiignorePath} exists but is not a regular file.`);
    }
    existing = fs.readFileSync(aiignorePath, 'utf8');
  }

  const { added, created } = planAiignore({ existing, suggested });
  const result = { path: aiignorePath, added, created, written: false, dryRun };

  if (added.length === 0 || dryRun) return result;

  fs.writeFileSync(aiignorePath, renderAiignore({ existing, added, created }), 'utf8');
  result.written = true;

  return result;
}

module.exports = {
  HEADER,
  parseRules,
  planAiignore,
  renderAiignore,
  writeAiignore
};
